# Exact reviewed notebook transport; executes its probe-mode code cells in order.
import base64, hashlib, json, zlib
from pathlib import Path
payload = zlib.decompress(base64.b64decode(''))
assert hashlib.sha256(payload).hexdigest() == '374a97daa38ad606b16d160780f3a334f5a2f34c6134b36a0037ccf742aaaf88'
saved = Path('/kaggle/working/FREM_S10_KAGGLE_NAMESPACE_CPU.ipynb')
if saved.exists() and saved.read_bytes() != payload:
    raise RuntimeError('existing reviewed notebook differs; preserve and stop')
saved.write_bytes(payload)
notebook = json.loads(payload)
for index, cell in enumerate(notebook['cells']):
    if cell['cell_type'] == 'code':
        print('NOTEBOOK_CELL', index, flush=True)
        exec(compile(''.join(cell['source']), 'reviewed-notebook-cell-'+str(index), 'exec'), globals())
